"""configloader — implement parse_config and get per README.md."""


def _coerce(raw):
    """Turn a raw value string into a bool, int, float, or str."""
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]

    lowered = raw.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False

    try:
        return int(raw)
    except ValueError:
        pass

    try:
        return float(raw)
    except ValueError:
        pass

    return raw


def parse_config(text):
    config = {}
    section = ""

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue

        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue

        if "=" not in line:
            continue

        key, _, raw = line.partition("=")
        config.setdefault(section, {})[key.strip()] = _coerce(raw.strip())

    return config


def get(config, dotted, default=None):
    section, _, key = dotted.rpartition(".")
    return config.get(section, {}).get(key, default)

